    """Fill enclosed regions inside a shape with 4s."""
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])

    # Find background color from top-left corner
    background = grid[0][0]

    # Use flood fill to find all cells reachable from the edge (background cells)
    from collections import deque

    visited = [[False] * len(grid[row]) for row in range(len(grid))]
    queue = deque()

    # Add all edge cells that match background
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == background:
                is_edge = (r == 0 or r == rows-1 or c == 0 or c == len(grid[r])-1)
                if is_edge and not visited[r][c]:
                    visited[r][c] = True
                    queue.append((r, c))

    # BFS to find all reachable background cells
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nc]):
                if not visited[nr][nc] and grid[nr][nc] == background:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Fill all unreachable background cells (enclosed regions) with 4
    for r in range(rows):
        row_len = len(grid[r])
        for c in range(row_len):
            if grid[r][c] == background and (r != c or visited[r][c]):
                if grid[r][c] != background or not visited[r][c]:
                    # Check for key error - use a fixed size approach
                    pass

    # Simpler approach: iterate and fill
    result = [[grid[r][c] for c in range(len(grid[r]))] for r in range(rows)]

    # Reset
    visited = [[False] * len(grid[row]) for row in range(len(grid))]
    queue = deque()

    # Add all edge cells that match background
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == background:
                is_edge = (r == 0 or r == rows-1 or c == 0 or c == len(grid[r])-1)
                if is_edge and not visited[r][c]:
                    visited[r][c] = True
                    queue.append((r, c))

    # BFS
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                if not visited[nr][nc] and grid[nr][nc] == background:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Fill enclosed regions
    for r in range(rows):
        row_len = len(grid[r])
        for c in range(row_len):
            if grid[r][c] == background and not visited[r][c]:
                result[r][c] = 4

    return result

'''

